interface Switchable{void on();void off();default void toggle(){on();}}class Fan implements Switchable{public void on(){System.out.println("Fan ON");}public void off(){System.out.println("Fan OFF");}}class Light implements Switchable{public void on(){System.out.println("Light ON");}public void off(){System.out.println("Light OFF");}}public class RemoteControl{public static void main(String[]x){Switchable[] a={new Fan(),new Light()};for(Switchable s:a)s.toggle();}}
